import 'package:flutter/material.dart'; import '../models/anime.dart'; import '../widgets/anime_widgets.dart'; import '../core/theme.dart';
class WatchlistPage extends StatelessWidget{const WatchlistPage({super.key,required this.items,required this.onOpen,required this.onRemove});final List<Anime> items;final ValueChanged<Anime> onOpen,onRemove;@override Widget build(BuildContext c)=>SafeArea(child:Column(children:[const Padding(padding:EdgeInsets.all(20),child:Align(alignment:Alignment.centerLeft,child:Text('My watchlist',style:TextStyle(fontSize:28,fontWeight:FontWeight.w900)))),Expanded(child:items.isEmpty?const Center(child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Icon(Icons.bookmark_border,size:55,color:appPurple),Text('Your list is waiting'),Text('Save anime from its detail page.',style:TextStyle(color:appMuted))])):GridView.builder(padding:const EdgeInsets.all(14),gridDelegate:const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:2,childAspectRatio:.62,crossAxisSpacing:12,mainAxisSpacing:12),itemCount:items.length,itemBuilder:(_,i)=>AnimePoster(anime:items[i],onTap:()=>onOpen(items[i]),onLongPress:()=>onRemove(items[i]))))]));}
